mapper.select:
SELECT CUSTOMER_ID code, CUSTOMER_NAME name FROM MST_CUSTOMER_INFO
IS_RATING_AGENCIES = #{isRatingAgencies, jdbcType=VARCHAR}
AND ( CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND CUSTOMER_ID = #{initValue, jdbcType=VARCHAR}
